cd /tmp/inspector && cat > Program.cs << 'EOF'
using System.Reflection;

// Check OpenAI extension methods
var oaiAsm = typeof(Microsoft.Extensions.AI.OpenAIChatClient).Assembly;
foreach (var t in oaiAsm.GetExportedTypes().Where(t => t.Name.Contains("Extension") || t.Name.Contains("Builder")).OrderBy(t => t.FullName))
{
    Console.WriteLine($"\n=== {t.FullName} ===");
    foreach (var m in t.GetMethods(BindingFlags.Public | BindingFlags.Static))
        Console.WriteLine($"  static {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
}

// Check CreateSessionAsync return type
var agentType = typeof(Microsoft.Agents.AI.ChatClientAgent);
var createSession = agentType.GetMethod("CreateSessionAsync");
Console.WriteLine($"\nCreateSessionAsync returns: {createSession?.ReturnType}");
if (createSession?.ReturnType.IsGenericType == true)
    Console.WriteLine($"  Generic arg: {createSession.ReturnType.GetGenericArguments()[0]}");

// Check AgentSession
Console.WriteLine("\n--- AgentSession (from base) ---");
var sessionType = createSession?.ReturnType.GetGenericArguments()[0];
if (sessionType != null)
{
    foreach (var p in sessionType.GetProperties(BindingFlags.Public | BindingFlags.Instance))
        Console.WriteLine($"  prop {p.PropertyType.Name} {p.Name}");
    foreach (var m in sessionType.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly).Where(m => !m.IsSpecialName))
        Console.WriteLine($"  method {m.ReturnType.Name} {m.Name}");
}
EOF
