 // ---------------------------------------------------------------------------
 // Research notes — shared state the agent writes to via the note-taking tool
 // ---------------------------------------------------------------------------
 public sealed class ResearchNotes
 {
     private readonly List<string> _notes = [];
     public IReadOnlyList<string> Notes => _notes;
     public void Add(string note) => _notes.Add(note);
     public void Clear() => _notes.Clear();
 }

 // ---------------------------------------------------------------------------
 // Tools exposed to the agent
 // ---------------------------------------------------------------------------
 public sealed class ResearchTools(ResearchNotes notes, ILogger<ResearchTools> logger)
 {
     private static readonly HttpClient Http = new()
     {
         DefaultRequestHeaders =
         {
             { "User-Agent", "ResearchAgent/1.0" },
             { "Accept", "application/json" }
         },
         Timeout = TimeSpan.FromSeconds(15)
     };

     [Description("Search the web for information on a query. Returns a JSON array of search results with title, url, and body.")]
     public async Task<string> SearchWeb(
         [Description("The search query string")] string query,
         [Description("Number of results to return (max 5)")] int count = 3)
     {
         count = Math.Clamp(count, 1, 5);
         logger.LogInformation("Searching web for: {Query}", query);

         try
         {
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
             var json = await Http.GetStringAsync(url);
             using var doc = JsonDocument.Parse(json);
             var root = doc.RootElement;

             var results = new List<object>();

             if (root.TryGetProperty("RelatedTopics", out var topics))
             {
                 foreach (var topic in topics.EnumerateArray())
                 {
                     if (results.Count >= count) break;
                     if (topic.TryGetProperty("Text", out var text) &&
                         topic.TryGetProperty("FirstURL", out var firstUrl))
                     {
                         results.Add(new
                         {
                             title = text.GetString()?[..Math.Min(text.GetString()!.Length, 80)],
                             url = firstUrl.GetString(),
                             body = text.GetString()
                         });
                     }
                 }
             }

             if (root.TryGetProperty("Abstract", out var abs) &&
                 abs.GetString() is { Length: > 0 } abstractText)
             {
                 results.Insert(0, new
                 {
                     title = root.TryGetProperty("Heading", out var h) ? h.GetString() : "Summary",
                     url = root.TryGetProperty("AbstractURL", out var u) ? u.GetString() : "",
                     body = abstractText
                 });
             }

             if (results.Count == 0)
                 return $"No results found for \"{query}\". Try rephrasing.";

             return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
         }
         catch (Exception ex)
         {
             logger.LogWarning(ex, "Web search failed");
             return $"Search failed: {ex.Message}. Try a different query.";
         }
     }

     [Description("Save a research note. Use this to record key findings, facts, and insights discovered during research.")]
     public string SaveNote(
         [Description("The note content to save")] string content)
     {
         notes.Add(content);
         logger.LogInformation("Note saved ({Count} total)", notes.Notes.Count);
         return $"Note saved. You now have {notes.Notes.Count} note(s).";
     }

     [Description("Retrieve all saved research notes.")]
     public string GetNotes()
     {
         if (notes.Notes.Count == 0)
             return "No notes saved yet.";

         return string.Join("\n---\n",
             notes.Notes.Select((n, i) => $"[Note {i + 1}] {n}"));
     }
 }

 // ---------------------------------------------------------------------------
 // Runner — wires up the agent and executes the research loop
 // ---------------------------------------------------------------------------
 public sealed class ResearchRunner(
     IChatClient chatClient,
     ResearchTools tools,
     ResearchNotes notes,
     ILogger<ResearchRunner> logger)
 {
     private const string SystemPrompt = """
         You are a thorough research agent. Given a topic, you must:
         1. Search the web for relevant information using multiple queries.
         2. Save important findings as notes using the SaveNote tool.
         3. Search for different angles and perspectives on the topic.
         4. After gathering enough information (at least 3 notes), retrieve
            your notes and provide a comprehensive summary.

         Be systematic: start broad, then drill into specifics.
         Always save key findings before moving on to the next search.
         """;

     public async Task RunAsync(string[] args)
     {
         var topic = args.Length > 0
             ? string.Join(' ', args)
             : PromptForTopic();

         Console.WriteLine($"\n🔍 Researching: {topic}\n");

         var aiTools = new List<AITool>
         {
             AIFunctionFactory.Create(tools.SearchWeb),
             AIFunctionFactory.Create(tools.SaveNote),
             AIFunctionFactory.Create(tools.GetNotes),
         };

         var agent = new ChatClientAgent(
             chatClient,
             instructions: SystemPrompt,
             name: "ResearchAgent",
             description: "An AI research agent that searches the web and takes notes.",
             tools: aiTools);

         var session = await agent.CreateSessionAsync("research-session");

         var runOptions = new ChatClientAgentRunOptions(new ChatOptions
         {
             Temperature = 0f,
             MaxOutputTokens = 2048,
         });

         var response = await agent.RunAsync(
             $"Research the following topic and provide a comprehensive summary: {topic}",
             session,
             runOptions);

         foreach (var message in response.Messages)
         {
             if (message.Role == ChatRole.Assistant && message.Text is { Length: > 0 } text)
             {
                 Console.WriteLine(text);
             }

             logger.LogDebug("Agent step: Role={Role}, ContentLength={Length}",
                 message.Role, message.Text?.Length ?? 0);
         }

         if (notes.Notes.Count > 0)
         {
             Console.ForegroundColor = ConsoleColor.Cyan;
             Console.WriteLine($"\n📝 {notes.Notes.Count} research note(s) were saved during this session.");
             Console.ResetColor();
         }
     }

     private static string PromptForTopic()
     {
         Console.Write("Enter a research topic: ");
         var topic = Console.ReadLine()?.Trim();
         return string.IsNullOrEmpty(topic)
             ? "Recent advances in quantum computing"
             : topic;
     }
 }
